CREATE TABLE public.h20_recipients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),legal_name text NOT NULL,public_name text NOT NULL,recipient_classification text NOT NULL CHECK (recipient_classification IN ('WATER_IMPACT_RECIPIENT','CHARITABLE_ORGANIZATION','GOVERNMENT_ENTITY','SERVICE_PROVIDER','OTHER_APPROVED_WATER_IMPACT_ENTITY')),verification_status text NOT NULL DEFAULT 'NOT_VERIFIED' CHECK (verification_status IN ('NOT_VERIFIED','PENDING_VERIFICATION','UNDER_REVIEW','VERIFIED','VERIFICATION_EXPIRED','VERIFICATION_FAILED')),verification_scope text,evidence_source text,verification_date date,verification_expires_at date,document_reference text,reviewed_by uuid,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.h20_recipients TO authenticated; GRANT ALL ON public.h20_recipients TO service_role; ALTER TABLE public.h20_recipients ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.h20_public_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_key text NOT NULL,claim_category text NOT NULL CHECK (claim_category IN ('PUBLIC_DISCLOSURE','ACCOUNTING_CLASSIFICATION','RECIPIENT_STATUS','DISTRIBUTION_STATUS','ROYALTY_STATUS','MARKET_STATUS','PRODUCTION_STATUS')),public_label text NOT NULL,public_content text NOT NULL,source_document_reference text NOT NULL,approval_status text NOT NULL DEFAULT 'PENDING_REVIEW' CHECK (approval_status IN ('PENDING_REVIEW','ADMIN_APPROVED','REJECTED','CORRECTED','EXPIRED')),verification_status text NOT NULL DEFAULT 'NOT_VERIFIED' CHECK (verification_status IN ('NOT_VERIFIED','PENDING_VERIFICATION','UNDER_REVIEW','VERIFIED','VERIFICATION_EXPIRED','VERIFICATION_FAILED')),effective_at timestamptz NOT NULL,expires_at timestamptz,reviewed_by uuid,reviewed_at timestamptz,supersedes_claim_id uuid REFERENCES public.h20_public_claims(id),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.h20_public_claims TO authenticated; GRANT ALL ON public.h20_public_claims TO service_role; ALTER TABLE public.h20_public_claims ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.h20_distributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES public.h20_recipients(id),distribution_type text NOT NULL CHECK (distribution_type IN ('DONATION','GRANT','PROJECT_PAYMENT','SERVICE_PAYMENT','INFRASTRUCTURE_FUNDING','REIMBURSEMENT','OTHER_APPROVED_DISTRIBUTION')),purpose text NOT NULL,amount numeric(38,8) NOT NULL CHECK (amount>0),currency text NOT NULL CHECK (currency~'^[A-Z0-9]{2,12}$'),status text NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED','ADMIN_APPROVED','SENT','SETTLED','REJECTED','CORRECTED')),approval_reference text NOT NULL,agreement_document_reference text NOT NULL,reporting_period text NOT NULL,transaction_id text,transaction_date timestamptz,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.h20_distributions TO authenticated; GRANT ALL ON public.h20_distributions TO service_role; ALTER TABLE public.h20_distributions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.h20_ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_group_id uuid NOT NULL,transaction_type text NOT NULL CHECK (transaction_type IN ('PRIMARY_SALE_RECEIPTS','PAYMENT_PROCESSING_COSTS','BLOCKCHAIN_TRANSACTION_COSTS','TAXES_AND_STATUTORY_CHARGES','NET_PRIMARY_SALE_RECEIPTS','WATER_IMPACT_ALLOCATION','ADMINISTRATIVE_ALLOCATION','MATCHING_LIQUIDITY_ALLOCATION','ROYALTY_RECEIVABLE','ROYALTY_RECEIVED','ROYALTY_DISTRIBUTION','SELLER_SALE_PROCEEDS','BUYER_REFUND_PAYABLE','PURCHASE_REFUND','MARKETPLACE_SALE','SELLER_WITHDRAWAL','PAYMENT_REVERSAL','WATER_IMPACT_DISTRIBUTION','CORRECTION')),source_account text NOT NULL,destination_account text NOT NULL,amount numeric(38,8) NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency~'^[A-Z0-9]{2,12}$'),transaction_reference text NOT NULL,business_purpose text NOT NULL,approval_reference text NOT NULL,ledger_status text NOT NULL DEFAULT 'CONFIRMED' CHECK(ledger_status IN ('PENDING','CONFIRMED','REVERSED','CORRECTED')),correction_of uuid REFERENCES public.h20_ledger_entries(id),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transaction_reference,transaction_type,source_account,destination_account),CHECK(source_account<>destination_account));
GRANT SELECT ON public.h20_ledger_entries TO authenticated; GRANT ALL ON public.h20_ledger_entries TO service_role; ALTER TABLE public.h20_ledger_entries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.h20_audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action text NOT NULL,record_type text NOT NULL,record_id uuid NOT NULL,actor_id uuid NOT NULL DEFAULT auth.uid(),reason text,previous_record jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.h20_audit_log TO authenticated; GRANT ALL ON public.h20_audit_log TO service_role; ALTER TABLE public.h20_audit_log ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.h20_is_approver() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT auth.uid() IS NOT NULL AND lower(coalesce(auth.jwt()->>'email',''))='1drrey@gmail.com' AND public.has_role(auth.uid(),'admin') $$; REVOKE ALL ON FUNCTION public.h20_is_approver() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.h20_is_approver() TO authenticated,service_role;
CREATE POLICY "H20 approver reads recipients" ON public.h20_recipients FOR SELECT TO authenticated USING(public.h20_is_approver()); CREATE POLICY "H20 approver creates unverified recipients" ON public.h20_recipients FOR INSERT TO authenticated WITH CHECK(public.h20_is_approver() AND created_by=auth.uid() AND verification_status<>'VERIFIED');
CREATE POLICY "H20 approver reads claims" ON public.h20_public_claims FOR SELECT TO authenticated USING(public.h20_is_approver()); CREATE POLICY "H20 approver creates pending claims" ON public.h20_public_claims FOR INSERT TO authenticated WITH CHECK(public.h20_is_approver() AND created_by=auth.uid() AND approval_status='PENDING_REVIEW');
CREATE POLICY "H20 approver reads distributions" ON public.h20_distributions FOR SELECT TO authenticated USING(public.h20_is_approver()); CREATE POLICY "H20 approver proposes distributions" ON public.h20_distributions FOR INSERT TO authenticated WITH CHECK(public.h20_is_approver() AND created_by=auth.uid() AND status='PROPOSED'); CREATE POLICY "H20 approver reads ledger" ON public.h20_ledger_entries FOR SELECT TO authenticated USING(public.h20_is_approver()); CREATE POLICY "H20 approver reads audit" ON public.h20_audit_log FOR SELECT TO authenticated USING(public.h20_is_approver());
CREATE OR REPLACE FUNCTION public.h20_block_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN RAISE EXCEPTION 'H20 records are append-only; create a correction record'; END $$;
CREATE TRIGGER h20_recipients_append_only BEFORE UPDATE OR DELETE ON public.h20_recipients FOR EACH ROW EXECUTE FUNCTION public.h20_block_mutation(); CREATE TRIGGER h20_claims_append_only BEFORE UPDATE OR DELETE ON public.h20_public_claims FOR EACH ROW EXECUTE FUNCTION public.h20_block_mutation(); CREATE TRIGGER h20_distributions_append_only BEFORE UPDATE OR DELETE ON public.h20_distributions FOR EACH ROW EXECUTE FUNCTION public.h20_block_mutation(); CREATE TRIGGER h20_ledger_append_only BEFORE UPDATE OR DELETE ON public.h20_ledger_entries FOR EACH ROW EXECUTE FUNCTION public.h20_block_mutation(); CREATE TRIGGER h20_audit_append_only BEFORE UPDATE OR DELETE ON public.h20_audit_log FOR EACH ROW EXECUTE FUNCTION public.h20_block_mutation();
CREATE OR REPLACE FUNCTION public.h20_review_claim(p_claim_id uuid,p_action text,p_verification_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE old_claim public.h20_public_claims; BEGIN IF NOT public.h20_is_approver() THEN RAISE EXCEPTION 'H20 production authorization denied'; END IF; IF p_action NOT IN ('ADMIN_APPROVED','REJECTED') THEN RAISE EXCEPTION 'Invalid review action'; END IF; SELECT * INTO old_claim FROM public.h20_public_claims WHERE id=p_claim_id AND approval_status='PENDING_REVIEW'; IF NOT FOUND THEN RAISE EXCEPTION 'Pending claim not found'; END IF; IF p_action='ADMIN_APPROVED' AND p_verification_status<>'VERIFIED' THEN RAISE EXCEPTION 'Public claims require verified evidence'; END IF; INSERT INTO public.h20_public_claims(claim_key,claim_category,public_label,public_content,source_document_reference,approval_status,verification_status,effective_at,expires_at,reviewed_by,reviewed_at,supersedes_claim_id,created_by) VALUES(old_claim.claim_key,old_claim.claim_category,old_claim.public_label,old_claim.public_content,old_claim.source_document_reference,p_action,p_verification_status,old_claim.effective_at,old_claim.expires_at,auth.uid(),now(),old_claim.id,old_claim.created_by); INSERT INTO public.h20_audit_log(action,record_type,record_id,reason,previous_record) VALUES(p_action,'PUBLIC_CLAIM',p_claim_id,'Administrative review',to_jsonb(old_claim)); END $$; REVOKE ALL ON FUNCTION public.h20_review_claim(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.h20_review_claim(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.h20_record_primary_sale(p_gross numeric,p_processing numeric,p_blockchain numeric,p_taxes numeric,p_currency text,p_transaction_reference text,p_business_purpose text,p_approval_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE gid uuid:=gen_random_uuid(); net numeric; water numeric; admin numeric; matching numeric; BEGIN IF NOT public.h20_is_approver() THEN RAISE EXCEPTION 'H20 production authorization denied'; END IF; IF p_gross<=0 OR least(p_processing,p_blockchain,p_taxes)<0 THEN RAISE EXCEPTION 'Invalid receipt amounts'; END IF; net:=p_gross-p_processing-p_blockchain-p_taxes; IF net<=0 THEN RAISE EXCEPTION 'Net primary-sale receipts must be positive'; END IF; water:=trunc(net*0.90,8); admin:=trunc(net*0.05,8); matching:=net-water-admin; INSERT INTO public.h20_ledger_entries(transaction_group_id,transaction_type,source_account,destination_account,amount,currency,transaction_reference,business_purpose,approval_reference,created_by) VALUES(gid,'WATER_IMPACT_ALLOCATION','NET_PRIMARY_SALE_RECEIPTS','WATER_IMPACT_TREASURY',water,upper(p_currency),p_transaction_reference,p_business_purpose,p_approval_reference,auth.uid()),(gid,'ADMINISTRATIVE_ALLOCATION','NET_PRIMARY_SALE_RECEIPTS','ADMINISTRATIVE_TREASURY',admin,upper(p_currency),p_transaction_reference,p_business_purpose,p_approval_reference,auth.uid()),(gid,'MATCHING_LIQUIDITY_ALLOCATION','NET_PRIMARY_SALE_RECEIPTS','MATCHING_LIQUIDITY_RESERVE',matching,upper(p_currency),p_transaction_reference,p_business_purpose,p_approval_reference,auth.uid()); INSERT INTO public.h20_audit_log(action,record_type,record_id,reason) VALUES('ALLOCATED_90_5_5','LEDGER_TRANSACTION',gid,'Confirmed net primary-sale receipt allocation'); RETURN gid; END $$; REVOKE ALL ON FUNCTION public.h20_record_primary_sale(numeric,numeric,numeric,numeric,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.h20_record_primary_sale(numeric,numeric,numeric,numeric,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.h20_public_claims_list() RETURNS TABLE(id uuid,claim_category text,public_label text,public_content text,approval_status text,verification_status text,effective_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT c.id,c.claim_category,c.public_label,c.public_content,c.approval_status,c.verification_status,c.effective_at FROM public.h20_public_claims c WHERE c.approval_status='ADMIN_APPROVED' AND c.verification_status='VERIFIED' AND c.effective_at<=now() AND(c.expires_at IS NULL OR c.expires_at>now()) AND NOT EXISTS(SELECT 1 FROM public.h20_public_claims n WHERE n.supersedes_claim_id=c.id) ORDER BY c.effective_at DESC $$; REVOKE ALL ON FUNCTION public.h20_public_claims_list() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.h20_public_claims_list() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.h20_public_accounting_summary() RETURNS TABLE(account_code text,display_name text,currency text,confirmed_amount numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT e.destination_account,CASE e.destination_account WHEN 'WATER_IMPACT_TREASURY' THEN 'Water-Impact Treasury' WHEN 'ADMINISTRATIVE_TREASURY' THEN 'AIQTP.com Administrative Treasury' WHEN 'MATCHING_LIQUIDITY_RESERVE' THEN 'Matching / Initial Liquidity-Support Reserve' ELSE e.destination_account END,e.currency,sum(e.amount) FROM public.h20_ledger_entries e WHERE e.ledger_status='CONFIRMED' AND e.destination_account IN('WATER_IMPACT_TREASURY','ADMINISTRATIVE_TREASURY','MATCHING_LIQUIDITY_RESERVE') GROUP BY e.destination_account,e.currency $$; REVOKE ALL ON FUNCTION public.h20_public_accounting_summary() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.h20_public_accounting_summary() TO anon,authenticated,service_role;